package graph

import (
	"fmt"
	"testing"
 "github.com/stretchr/testify/assert"

	"github.com/gookit/color"
	"github.com/jesseduffield/lazygit/pkg/commands/models"
	"github.com/jesseduffield/lazygit/pkg/gui/presentation/authors"
	"github.com/jesseduffield/lazygit/pkg/gui/style"
	"github.com/jesseduffield/lazygit/pkg/utils"
	"github.com/xo/terminfo"
)

func BenchmarkRenderCommitGraphVariants(b *testing.B) {
	oldColorLevel := color.ForceSetColorLevel(terminfo.ColorLevelMillions)
	defer color.ForceSetColorLevel(oldColorLevel)

	for _, count := range []int{50, 500} {
		for _, symbols := range []struct {
			name string
			set  SymbolSet
		}{
			{name: "box", set: BoxDrawingSymbols},
			{name: "branch", set: BranchDrawingSymbols},
		} {
			for _, selected := range []bool{false, true} {
				b.Run(fmt.Sprintf("commits=%d/symbols=%s/selected=%t", count, symbols.name, selected), func(b *testing.B) {
					commits := generateCommits(&utils.StringPool{}, count)
					var selectedHash *string
					if selected {
						selectedHash = commits[count/2].HashPtr()
					}
					getStyle := func(commit *models.Commit) *style.TextStyle {
						return authors.AuthorStyle(commit.AuthorName)
					}
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						RenderCommitGraph(commits, selectedHash, getStyle, symbols.set)
					}
				})
			}
		}
	}
}

func auditSequentialGraph(pipeSets [][]Pipe, commits []*models.Commit, selected *string, symbols SymbolSet) []string {
 lines := make([]string, len(pipeSets))
 for k, pipes := range pipeSets {
  var previous *models.Commit
  if k > 0 { previous = commits[k-1] }
  lines[k] = renderPipeSet(pipes, selected, previous, symbols)
 }
 return lines
}
func TestAuditGraphSequentialParity(t *testing.T) {
 commits := generateCommits(&utils.StringPool{}, 500)
 pipes := GetPipeSets(commits, func(*models.Commit) *style.TextStyle { return &style.FgDefault })
 for _, rows := range []int{1, 8, 40, 120} {
  for _, symbols := range []SymbolSet{BoxDrawingSymbols, BranchDrawingSymbols} {
   for _, selected := range []*string{nil, commits[100+rows/2].HashPtr()} {
    actual := RenderAux(pipes[100:100+rows], commits[100:100+rows], selected, symbols)
    want := auditSequentialGraph(pipes[100:100+rows], commits[100:100+rows], selected, symbols)
    assert.Equal(t, want, actual)
   }
  }
 }
}
var auditGraphOutput []string
func BenchmarkAuditGraphViewport(b *testing.B) {
 commits := generateCommits(&utils.StringPool{}, 500)
 pipes := GetPipeSets(commits, func(*models.Commit) *style.TextStyle { return &style.FgDefault })
 for _, rows := range []int{1, 8, 40, 120} {
  for _, sequential := range []bool{false, true} {
   b.Run(fmt.Sprintf("rows=%d/sequential=%t", rows, sequential), func(b *testing.B) {
    b.ReportAllocs()
    for b.Loop() {
     if sequential { auditGraphOutput = auditSequentialGraph(pipes[100:100+rows], commits[100:100+rows], nil, BoxDrawingSymbols) } else { auditGraphOutput = RenderAux(pipes[100:100+rows], commits[100:100+rows], nil, BoxDrawingSymbols) }
    }
   })
  }
 }
}

