package gocui

import (
	"fmt"
	"strings"
	"testing"
)

func BenchmarkPasteText(b *testing.B) {
	for _, size := range []int{1000, 10000, 100000} {
		b.Run(fmt.Sprintf("bytes=%d", size), func(b *testing.B) {
			pasted := strings.Repeat("some pasted text\n", size/17)
			b.SetBytes(int64(len(pasted)))
			b.ReportAllocs()
			for b.Loop() {
				area := &TextArea{content: "prefix suffix", cursor: len("prefix "), AutoWrapWidth: 72, AutoWrap: true}
				area.TypeString(pasted)
			}
		})
	}
}

func BenchmarkAuditEditorVerticalMovement(b *testing.B) {
 for _, count := range []int{100, 1000, 10000} {
  for _, bottom := range []bool{false, true} {
   b.Run(fmt.Sprintf("lines=%d/bottom=%t", count, bottom), func(b *testing.B) {
    area := &TextArea{content: strings.Repeat("some text for a line\n", count)}
    area.updateCells()
    row := 2
    if bottom { row = count-2 }
    area.SetCursor2D(5, row)
    b.ReportAllocs()
    b.ResetTimer()
    for b.Loop() { area.MoveCursorUp(); area.MoveCursorDown() }
   })
  }
 }
}

