func TestAuditGraphOccupancyCounts(t *testing.T) {
 for _, width := range []int{4,16,64} {
  pool := &utils.StringPool{}
  commit := models.NewCommit(pool, models.NewCommitOpts{Hash:"selected", Parents:[]string{"parent"}})
  pipes := make([]Pipe, width)
  for i := range pipes {
   target := fmt.Sprintf("other-%d", i)
   toHash := models.NewCommit(pool, models.NewCommitOpts{Hash:target}).HashPtr()
   if i == width-1 { toHash = commit.HashPtr() }
   pipes[i] = Pipe{toPos:int16(i), toHash:toHash, kind:CONTINUES, style:&style.FgDefault}
  }
  auditContinuingProbes, auditNewProbes = 0, 0
  getNextPipes(pipes, commit, func(*models.Commit) *style.TextStyle { return &style.FgDefault })
  t.Logf("continuing width=%d probes=%d", width, auditContinuingProbes)
  parents := make([]string,width)
  for i := range parents { parents[i]=fmt.Sprintf("parent-%d",i) }
  merge := models.NewCommit(pool, models.NewCommitOpts{Hash:"merge",Parents:parents})
  auditContinuingProbes, auditNewProbes = 0, 0
  getNextPipes(nil,merge,func(*models.Commit) *style.TextStyle { return &style.FgDefault })
  t.Logf("new parents=%d probes=%d",width,auditNewProbes)
 }
}

